// @bun
// packages/session-finder/src/index.ts
import { randomUUID } from "crypto";

// packages/session-finder/src/match.ts
import { realpathSync } from "fs";
var GLOBAL_PROJECT = "global";
function resolve(path) {
  try {
    return realpathSync(path);
  } catch {
    return path.replace(/\/+$/, "");
  }
}
function sameProject(a, b, resolvePath = resolve) {
  if (a.projectID !== b.projectID)
    return false;
  if (a.projectID !== GLOBAL_PROJECT)
    return true;
  return resolvePath(a.location.directory) === resolvePath(b.location.directory);
}
function rejectReason(source, target, resolvePath) {
  if (source.id === target.id)
    return "That is the current session.";
  if (!sameProject(source, target, resolvePath)) {
    return `Session ${target.id} belongs to another project (${target.location.directory}). ` + `Reopen it with \`opencode --session ${target.id}\`.`;
  }
  return;
}

// packages/session-finder/src/pending.ts
var waiting = new Map;
function waitForReply(requestID, timeoutMs, signal) {
  return new Promise((resolve2) => {
    const finish = (action) => {
      clearTimeout(timer);
      signal?.removeEventListener("abort", abort);
      waiting.delete(requestID);
      resolve2(action);
    };
    const abort = () => finish(undefined);
    const timer = setTimeout(() => finish(undefined), timeoutMs);
    signal?.addEventListener("abort", abort, { once: true });
    waiting.set(requestID, finish);
  });
}
function reply(requestID, action) {
  const finish = waiting.get(requestID);
  if (!finish)
    return false;
  finish(action);
  return true;
}

// packages/session-finder/src/present.ts
var LIMIT = 30;

// packages/session-finder/src/rpc.ts
var requestSchema = {
  type: "object",
  properties: {
    requestID: { type: "string" },
    sourceSessionIDs: { type: "array", items: { type: "string" } },
    sessionID: { type: "string" },
    rootSessionID: { type: "string" },
    root: { type: "boolean" },
    closeSource: { type: "boolean" }
  },
  required: ["requestID", "sourceSessionIDs", "sessionID", "rootSessionID", "root", "closeSource"],
  additionalProperties: false
};
var handledSchema = {
  type: "object",
  properties: {
    requestID: { type: "string" },
    action: { type: "string", enum: ["tab", "route"] }
  },
  required: ["requestID", "action"],
  additionalProperties: false
};
var searchSchema = {
  type: "object",
  properties: {
    query: { type: "string", minLength: 1 },
    sessionID: { type: "string" },
    directory: { type: "string" },
    limit: { type: "integer", minimum: 1 },
    titles: { type: "boolean" }
  },
  required: ["query"],
  additionalProperties: false
};
var SessionSearchRpc = {
  id: "opencode-session-finder",
  methods: {
    handled: { input: handledSchema, output: { type: "object", additionalProperties: false } },
    search: { input: searchSchema, output: { type: "object" } }
  },
  events: {
    requested: { schema: requestSchema }
  }
};

// packages/session-finder/src/run.ts
function workerURL(base = import.meta.url) {
  const typescript = new URL(base).pathname.endsWith(".ts");
  return new URL(typescript ? "./worker.ts" : "./worker.js", base);
}
function runSearch(options, signal, url = workerURL()) {
  return new Promise((resolve2, reject) => {
    if (signal?.aborted) {
      reject(new Error("Search cancelled"));
      return;
    }
    const worker = new Worker(url);
    let settled = false;
    const settle = (finish) => {
      if (settled)
        return;
      settled = true;
      signal?.removeEventListener("abort", abort);
      worker.terminate();
      finish();
    };
    const abort = () => settle(() => reject(new Error("Search cancelled")));
    signal?.addEventListener("abort", abort, { once: true });
    worker.onmessage = (event) => {
      const reply2 = event.data;
      settle(() => ("error" in reply2) ? reject(new Error(reply2.error)) : resolve2(reply2.result));
    };
    worker.onerror = (event) => {
      settle(() => reject(new Error(event.message || "Search worker failed")));
    };
    worker.addEventListener("close", (event) => {
      const code = event.code;
      settle(() => reject(new Error(`Search worker exited (code ${code ?? "unknown"})`)));
    });
    worker.postMessage(options);
  });
}

// packages/session-finder/src/db.ts
var SOURCES = ["tools", "reasoning", "system"];

// packages/session-finder/src/tool.ts
var SEARCH_DESCRIPTION = [
  "Search previous OpenCode sessions for a keyword or sentence, newest match first.",
  "Use it when the user asks which earlier session discussed something, where a phrase,",
  "command, or decision came up, or wants to return to a past conversation. The session",
  "list API matches titles only; this tool searches message text.",
  "",
  "Matching is literal and case-insensitive: pass the wording as is, without wildcards or",
  "regular expressions. User messages, assistant replies, compaction summaries, and titles",
  "are always searched, and the current session is excluded.",
  "",
  "When a search finds nothing, the tool retries it with `words` for a multi-word query,",
  "then with tool output included. `searches` lists each search that ran; `mode` and",
  "`include` describe the one that produced the results.",
  "",
  "Present the results: list each session with its title, ID, directory, and the date of",
  "its last match, and quote the most relevant excerpt. List sessions whose `same_project`",
  "is true first and mark them as the current project. Mention `total_sessions` when it is",
  "larger than the number shown. When `include` contains `tools` and you did not request",
  "it, say that nothing matched the conversation text and the matches come from tool calls",
  "and their output. If nothing matches, say which searches ran.",
  "",
  "When the user wants to act on a session, ask in one question tool call. If several",
  "sessions match, ask which one, labeling each option with the session title and putting its",
  "ID and date in the description. Ask what to do with it, offering only the actions that apply:",
  "- Switch and close search tab: only when `same_project` is true; recommend it first. Call",
  "  `open_session` with `close_source: true`.",
  "- Open session: only when `same_project` is true. Call `open_session` without `close_source`.",
  "- Summarize here: search again with `session_id`, more `excerpts`, and a larger `context`,",
  "  and summarize the matches.",
  "- Show more matches: only when `total_sessions` is larger than shown. Search again with a",
  "  larger `limit`.",
  "If `open_session` fails, show its error instead of retrying, and tell the user to reopen the",
  "session with `opencode --session <id>`. For sessions of other projects, give that command",
  "directly."
].join(`
`);
var OPEN_DESCRIPTION = "Open another OpenCode session of the current project in the user's terminal, focusing its " + "tab or switching to it. Optionally close the source tab after opening, preserving its " + "conversation in history. Only call it after the user chooses that action. It fails for " + "sessions of other projects.";
var searchInput = {
  type: "object",
  properties: {
    query: { type: "string", minLength: 1, description: "Keyword or sentence to find." },
    words: {
      type: "boolean",
      description: "Match sessions that contain every word, in any message, in any order."
    },
    include: {
      type: "array",
      items: { type: "string", enum: [...SOURCES] },
      description: "Extra sources to search. `tools` covers commands, file reads, and tool output, and is " + "several times slower. `reasoning` and `system` cover model reasoning and harness messages."
    },
    fallback: {
      type: "boolean",
      description: "Set to false to run only the requested search, without retries."
    },
    session_id: {
      type: "string",
      pattern: "^ses",
      description: "Only this session, for example to read more of its matches."
    },
    directory: {
      type: "string",
      description: "Only sessions in this directory or its subdirectories."
    },
    current_project: {
      type: "boolean",
      description: "Only sessions of the current project, including its other worktrees."
    },
    since: {
      type: "string",
      pattern: "^\\d{4}-\\d{2}-\\d{2}$",
      description: "Only matches on or after this date (YYYY-MM-DD)."
    },
    until: {
      type: "string",
      pattern: "^\\d{4}-\\d{2}-\\d{2}$",
      description: "Only matches before this date (YYYY-MM-DD)."
    },
    limit: { type: "integer", minimum: 1, description: "Maximum sessions to return. Default 10." },
    excerpts: {
      type: "integer",
      minimum: 0,
      description: "Maximum excerpts per session. Default 3."
    },
    context: {
      type: "integer",
      minimum: 0,
      description: "Characters of context around a match. Default 100."
    },
    include_current: {
      type: "boolean",
      description: "Also search the current session."
    }
  },
  required: ["query"],
  additionalProperties: false
};
var openInput = {
  type: "object",
  properties: {
    session_id: { type: "string", pattern: "^ses", description: "ID of the session to open." },
    close_source: {
      type: "boolean",
      description: "Close the source tab after opening the destination. Defaults to false. Does not delete history."
    }
  },
  required: ["session_id"],
  additionalProperties: false
};
function searchOptions(input, caller) {
  return {
    query: input.query,
    database: caller.database,
    words: input.words,
    include: input.include,
    fallback: input.fallback,
    sessionID: input.session_id,
    directory: input.directory,
    currentProject: input.current_project,
    since: input.since,
    until: input.until,
    limit: input.limit,
    excerpts: input.excerpts,
    context: input.context,
    includeCurrent: input.include_current,
    currentSessionID: caller.sessionID,
    cwd: caller.directory
  };
}

// packages/session-finder/src/index.ts
var REPLY_TIMEOUT_MS = 3000;
var MAX_ANCESTORS = 10;
async function ancestry(get, session) {
  const ids = [session.id];
  let parentID = session.parentID;
  while (parentID && ids.length <= MAX_ANCESTORS) {
    ids.push(parentID);
    parentID = (await get({ sessionID: parentID })).parentID;
  }
  return ids;
}
function describe(action) {
  return action === "tab" ? "focused its tab" : "navigated to it";
}
function databaseOption(options) {
  if (!options || typeof options !== "object")
    return;
  const value = options["database"];
  return typeof value === "string" && value ? value : undefined;
}
var src_default = {
  id: "opencode-session-finder",
  async setup(ctx) {
    const get = ctx.session.get;
    const database = databaseOption(ctx.options);
    const rpc = await ctx.rpc.register(SessionSearchRpc, {
      handled: async (input) => {
        const { requestID, action } = input;
        reply(requestID, action);
        return {};
      },
      search: async (input, { signal }) => {
        const request = input;
        const result = await runSearch({
          query: request.query,
          database,
          limit: request.limit ?? LIMIT,
          excerpts: 1,
          currentSessionID: request.sessionID,
          cwd: request.directory ?? ctx.location.directory,
          titles: request.titles ?? false
        }, signal);
        return result;
      }
    });
    const tools = await ctx.tool.transform((editor) => {
      editor.add({
        name: "search_sessions",
        description: SEARCH_DESCRIPTION,
        input: searchInput,
        execute: async (input, { sessionID, signal }) => {
          const session = await get({ sessionID });
          const result = await runSearch(searchOptions(input, {
            sessionID,
            directory: session.location.directory,
            database
          }), signal);
          return { content: JSON.stringify(result, null, 2) };
        }
      });
      editor.add({
        name: "open_session",
        description: OPEN_DESCRIPTION,
        input: openInput,
        execute: async (input, { sessionID, signal }) => {
          const { session_id: targetID, close_source: closeSource = false } = input;
          const source = await get({ sessionID });
          let target;
          try {
            target = await get({ sessionID: targetID });
          } catch {
            throw new Error(`Session ${targetID} was not found.`);
          }
          const reason = rejectReason(source, target);
          if (reason)
            throw new Error(reason);
          const sourceSessionIDs = await ancestry(get, source);
          const targetSessionIDs = await ancestry(get, target);
          const requestID = randomUUID();
          const replied = waitForReply(requestID, REPLY_TIMEOUT_MS, signal);
          await rpc.events.emit("requested", {
            requestID,
            sourceSessionIDs,
            sessionID: target.id,
            rootSessionID: targetSessionIDs[targetSessionIDs.length - 1],
            root: !target.parentID,
            closeSource
          });
          const action = await replied;
          if (!action) {
            throw new Error(`No terminal showing this session opened ${target.id}. ` + `Reopen it with \`opencode --session ${target.id}\`.`);
          }
          const title = target.title ? `"${target.title}" (${target.id})` : target.id;
          return { content: `Opened ${title}: the terminal ${describe(action)}.` };
        }
      });
    });
    return async () => {
      await tools.dispose();
      await rpc.dispose();
    };
  }
};
export {
  src_default as default
};
